async function svgFilesToShapes(files){const shapes=[];for(const file of [...files].slice(0,60)){if(!/\.svg$/i.test(file.name))continue;try{
 const svgText=await file.text();if(svgText.length>2000000)throw Error('Файл слишком большой');const xml=new DOMParser().parseFromString(svgText,'image/svg+xml');if(xml.querySelector('parsererror')||xml.documentElement.localName!=='svg')throw Error('Неверный SVG');const root=xml.documentElement;
 let vb=(root.getAttribute('viewBox')||'').trim().split(/[\s,]+/).map(Number);if(vb.length!==4||vb.some(v=>!Number.isFinite(v))||vb[2]<=0||vb[3]<=0){const w=parseFloat(root.getAttribute('width'))||100,h=parseFloat(root.getAttribute('height'))||100;vb=[0,0,w,h]}
 const scale=Math.min(90/vb[2],90/vb[3]),x0=5+(90-vb[2]*scale)/2-vb[0]*scale,y0=5+(90-vb[3]*scale)/2-vb[1]*scale;
 const norm=new DOMMatrix([scale,0,0,scale,x0,y0]),parts=[];const allowed=new Set(['path','polygon','polyline','rect','circle','ellipse']);
 function walk(node,matrix){const tag=node.localName?.toLowerCase();const current=matrix.multiply(svgTransformMatrix(node.getAttribute?.('transform')||''));if(allowed.has(tag)){const d=svgPathForNode(node);if(d&&/^[\s\d.eE+\-,MmZzLlHhVvCcSsQqTtAa]+$/.test(d))parts.push({d,matrix:[current.a,current.b,current.c,current.d,current.e,current.f]})}
 for(const child of node.children||[])if(['g',...allowed].includes(child.localName?.toLowerCase()))walk(child,current)}
 walk(root,norm);if(!parts.length||parts.length>500)throw Error('Не найдено поддерживаемых контуров');shapes.push({name:file.name.replace(/\.svg$/i,''),d:'M 0 0',parts});
 }catch(err){console.warn(err);toast('SVG «'+file.name+'»: '+err.message)}}
 if(!shapes.length){toast('Не найдено подходящих SVG');return}app.shapeQueue=shapes.slice(1);shapeModalOpen(shapes[0],'Импорт SVG');}

