function weightLabel(weight,style=''){
 const labels={100:'Thin',200:'ExtraLight',300:'Light',400:'Regular',500:'Medium',600:'SemiBold',700:'Bold',800:'ExtraBold',900:'Black'};
 return (labels[Number(weight)]||String(weight))+(style==='italic'?' Italic':'');
}
function inferFontMeta(filename,fallbackFamily=''){
 const stem=filename.replace(/\.(ttf|otf|woff2?)$/i,'').replace(/[_]+/g,' ').trim();
 const match=stem.match(/(?:[-\s]+)(Extra[ -]?Light|Ultra[ -]?Light|Extra[ -]?Bold|Semi[ -]?Bold|Demi[ -]?Bold|Ultra[ -]?Bold|Medium|Regular|Normal|Book|Thin|Light|Bold|Black|Heavy|Italic|Oblique)(?:[ -]?(Italic|Oblique))?$/i);
 const suffix=match?(match[1]+' '+(match[2]||'')).trim():'';
 const cleaned=(match?stem.slice(0,match.index):stem).trim().replace(/[ -]+$/,'');
 const style=/italic|oblique/i.test(suffix)?'italic':'normal';
 const weight=/thin/i.test(suffix)?100:/extra.?light|ultra.?light/i.test(suffix)?200:/light/i.test(suffix)?300:/medium/i.test(suffix)?500:/semi.?bold|demi.?bold/i.test(suffix)?600:/extra.?bold|ultra.?bold/i.test(suffix)?800:/black|heavy/i.test(suffix)?900:/bold/i.test(suffix)?700:400;
 return {family:(fallbackFamily||cleaned||stem||'Мой шрифт').trim(),weight,style};
}
function normaliseFont(f){const meta=inferFontMeta(f.name||'Мой шрифт');f.family=f.family||meta.family;f.weight=Number(f.weight??meta.weight)||400;f.style=f.style||meta.style||'normal';return f}
function fontFamilies(){const names=[...builtinFonts];for(const raw of app.fonts){const f=normaliseFont(raw);if(!names.some(n=>n.toLowerCase()===f.family.toLowerCase()))names.push(f.family)}return names}
function fontVariants(family){const variants=app.fonts.filter(f=>normaliseFont(f).family===family);
 if(!variants.length)return [['400:normal','Regular'],['500:normal','Medium'],['600:normal','SemiBold'],['700:normal','Bold'],['800:normal','ExtraBold'],['900:normal','Black']];
 return [...new Map(variants.map(f=>[`${f.weight}:${f.style}`,[`${f.weight}:${f.style}`,weightLabel(f.weight,f.style)]])).values()].sort((a,b)=>Number.parseInt(a[0])-Number.parseInt(b[0]));
}
function regularVariant(family){const options=fontVariants(family);return options.find(x=>x[0]==='400:normal')?.[0]||[...options].sort((a,b)=>Math.abs(parseInt(a[0])-400)-Math.abs(parseInt(b[0])-400)||(a[0].endsWith('normal')?-1:1))[0]?.[0]||'400:normal'}
function chosenVariant(e){return `${e.fontWeight||'400'}:${e.fontStyle||'normal'}`}
function v41ProjectFontFamilies(){
 const pid=app.doc?.projectId||app.currentProjectId;
 const docs=[...app.docs.filter(d=>d.projectId===pid)];
 if(app.doc?.projectId===pid){const ix=docs.findIndex(d=>d.id===app.doc.id);if(ix>=0)docs[ix]=app.doc;else docs.push(app.doc)}
 for(const tab of documentTabSession.tabs){if(tab.doc.projectId!==pid)continue;const ix=docs.findIndex(d=>d.id===tab.doc.id);if(ix>=0)docs[ix]=tab.doc;else docs.push(tab.doc)}
 const names=new Map();for(const d of docs){const slideElements=(d.slides||[]).flatMap(x=>x.elements||[]);for(const e of [...(d.elements||[]),...slideElements])if(e.type==='text'){
  const name=(e.fontFamily||'Arial').trim();if(!names.has(name.toLowerCase()))names.set(name.toLowerCase(),name);
 }}return [...names.values()];
}
const v41FontCategories=[['all','Все шрифты'],['custom','Пользовательские'],['project','Шрифты проекта']];
