// fields continue to point at the active canvas for the existing paint engine.
const SLIDE_FIELDS=['width','height','background','backgroundAlpha','palette','rulers','groups','elements'];
// Windows-safe names, used consistently for live card titles and PNG downloads.
function sanitizeCardTitle(value){return String(value??'').replace(/[\r\n\t]+/g,' ').replace(/[\\\/:*?"'«»„“”.,]/g,'').replace(/[\x00-\x1f\x7f]/g,' ').replace(/\s+/g,' ').trim().replace(/[ .]+$/,'').slice(0,120)||'Без названия'}
function cardTitleSource(d){if(!d)return null;
 if(d.type==='card'&&d.slides?.length){for(let i=0;i<d.slides.length;i++){
  const elems=i===d.activeSlideIndex?d.elements:d.slides[i].elements;
  const e=elems?.find(x=>x.type==='text'&&x.isTitleLayer);if(e)return e;
 }}return d.elements?.find(x=>x.type==='text'&&x.isTitleLayer)||null}
function syncAutoCardTitle(d=app.doc){if(!d||d.type!=='card'||d.hasCustomName)return false;const source=cardTitleSource(d);if(!source)return false;const next=sanitizeCardTitle(source.text);if(d.title===next)return false;d.title=next;if(d===app.doc)updateProjectBadge();return true}
function markCardNameManual(d=app.doc){if(d?.type==='card')d.hasCustomName=true}
function resetAutoCardName(){const d=app.doc;if(d?.type!=='card')return;if(document.activeElement?.matches?.('[data-doc=\"title\"]'))document.activeElement.blur();d.hasCustomName=false;syncAutoCardTitle(d);commit('Автоматическое название карточки');refreshInspector();updateProjectBadge()}

function makeSlideFromDoc(d){const s={id:uid(),label:'',createdAt:Date.now()};for(const key of SLIDE_FIELDS)if(d[key]!==undefined)s[key]=clone(d[key]);return s}
// A template insertion is a new canvas; a root/active-slide mirror is not.
function makeTemplateSlide(template){return makeSlideFromDoc(remapCanvasGraph(template,uid,{reservedIds:canvasGraphIds(app.doc||{})}))}
function cloneDocumentGraph(source){return remapDocumentGraph(source,uid,{reservedIds:app.docs.flatMap(canvasGraphIds)})}
function ensureCardSlides(d){if(d?.type!=='card')return;
 if(!Array.isArray(d.slides)||!d.slides.length){d.slides=[makeSlideFromDoc(d)];d.activeSlideIndex=0}
 d.activeSlideIndex=Math.max(0,Math.min(d.slides.length-1,Number(d.activeSlideIndex)||0));
 for(const slide of d.slides){slide.id ||= uid();slide.elements ||= [];slide.groups ||= [];slide.background ||= '#ffffff';slide.width ||= d.width;slide.height ||= d.height}
}
// Keep absent optional defaults in old slides until their effective values change.
function syncCurrentSlide(d=app.doc){if(d?.type!=='card')return;ensureCardSlides(d);const old=d.slides[d.activeSlideIndex];if(!old)return;for(const key of SLIDE_FIELDS)if(d[key]!==undefined){if(old[key]===undefined&&((key==='backgroundAlpha'&&d[key]===100)||(['rulers','palette'].includes(key)&&Array.isArray(d[key])&&!d[key].length)))continue;old[key]=clone(d[key])}}
function slideAsDoc(d,index){if(d.type!=='card'||!d.slides?.length)return d;
 const i=Math.max(0,Math.min(d.slides.length-1,index));const item={...d,rulers:[],palette:[],backgroundAlpha:100};for(const key of SLIDE_FIELDS)if(d.slides[i]?.[key]!==undefined)item[key]=d.slides[i][key];return item;
}
function applySlideToRoot(d,index){ensureCardSlides(d);if(d.type!=='card')return;
 const slide=d.slides[index];if(!slide)return;d.rulers=[];d.palette=[];d.backgroundAlpha=100;for(const key of SLIDE_FIELDS)if(slide[key]!==undefined)d[key]=clone(slide[key]);d.activeSlideIndex=index;boundaryRememberDoc(d);
}
