function ensureGroupData(d){
 d.groups ||= [];
 const known=new Set(d.groups.map(g=>g.id));
 for(const e of d.elements)if(e.groupId&&!known.has(e.groupId)){
  d.groups.push({id:e.groupId,name:e.groupLabel||'Группа',parentId:null,collapsed:false,visible:true,locked:false});known.add(e.groupId)
 }
 for(const g of d.groups){if(g.visible===undefined)g.visible=true;if(g.locked===undefined)g.locked=false;}
}
function groupInfo(id){return app.doc?.groups?.find(g=>g.id===id)||null}
function groupAncestor(child,parent){let g=groupInfo(child),guard=0;while(g&&guard++<100){if(g.id===parent)return true;g=groupInfo(g.parentId)}return false}
function groupMembers(id){return app.doc.elements.filter(e=>e.groupId&&groupAncestor(e.groupId,id))}
// Inherited group flags never overwrite an individual layer's own settings.
// Keep a document argument for rendering inactive canvases in a series and exporting PNG.
function ancestorGroups(groupId,doc=app.doc){
 const groups=doc?.groups||[],chain=[],seen=new Set();let id=groupId;
 while(id&&!seen.has(id)){seen.add(id);const g=groups.find(x=>x.id===id);if(!g)break;chain.push(g);id=g.parentId||null;}
 return chain;
}
function isLayerVisible(e,doc=app.doc){return !!e&&e.visible!==false&&!ancestorGroups(e.groupId,doc).some(g=>g.visible===false)}
function isLayerLocked(e,doc=app.doc){return !!e&&(e.locked===true||ancestorGroups(e.groupId,doc).some(g=>g.locked===true))}
function groupEffectiveVisible(g,doc=app.doc){return !!g&&!ancestorGroups(g.id,doc).some(p=>p.visible===false)}
function groupEffectiveLocked(g,doc=app.doc){return !!g&&ancestorGroups(g.id,doc).some(p=>p.locked===true)}
function groupDescendantIds(id){return app.doc.groups.filter(g=>groupAncestor(g.id,id)).map(g=>g.id)}
function expandSelection(ids,isolated=false){if(isolated)return ids;const chosen=new Set(ids);for(const id of ids){const e=app.doc.elements.find(x=>x.id===id);if(e?.groupId){let g=groupInfo(e.groupId);while(g?.parentId)g=groupInfo(g.parentId);if(g)for(const m of groupMembers(g.id))chosen.add(m.id)}}return app.doc.elements.filter(e=>chosen.has(e.id)).map(e=>e.id)}
function selectGroup(id,toggle=false){
 const members=groupMembers(id).map(e=>e.id);
 const gs=toggle?[...(app.selectedGroupIds||[])]:[];
 if(toggle&&gs.includes(id))gs.splice(gs.indexOf(id),1);else gs.push(id);
 const els=new Set(toggle?app.selectedIds:[]);
 if(toggle&&app.selectedGroupIds?.includes(id))for(const x of members)els.delete(x);else for(const x of members)els.add(x);
 setSelected([...els],true);
 app.selectedGroupIds=gs;
 app.focusGroupId=gs.length===1?gs[0]:null;
 refreshLayers();refreshInspector();updateQuickBubble();
}
function groupSelected(){
 const id=uid();let plan;
 try{plan=planLayerGroup(app.doc,app.selectedIds,app.selectedGroupIds||[],id)}catch(error){toast(error.message);return false}
 const grp={id,name:'Группа '+(()=>{let n=1;while(app.doc.groups.some(g=>g.name==='Группа '+n))n++;return n})(),parentId:plan.parentId,collapsed:false,visible:true,locked:false};
 rememberLayerSelection();
 app.doc.groups.push(grp);
 for(const e of plan.leaves){e.groupId=grp.id;delete e.groupLabel}
 for(const g of plan.roots)g.parentId=grp.id;
 app.doc.elements=plan.elements;
 const from=groupMembers(grp.id);
 setSelected(from.map(e=>e.id),true);app.selectedGroupIds=[grp.id];app.focusGroupId=grp.id;commit();refreshLayers();refreshInspector();toast('Группа создана');return true;
}
function ungroupSelected(){
 const targets=(app.selectedGroupIds?.length?app.selectedGroupIds:app.focusGroupId?[app.focusGroupId]:[]);
 // Legacy selection of all sibling members also supports Ctrl+G to ungroup.
 if(!targets.length){const a=picked(),g=a[0]?.groupId;if(g&&groupMembers(g).length===a.length&&a.every(e=>groupAncestor(e.groupId,g)))targets.push(g)}
 if(!targets.length)return;
 for(const id of [...new Set(targets)]){
  const g=groupInfo(id);if(!g)continue;
  for(const e of app.doc.elements)if(e.groupId===id)e.groupId=g.parentId||null;
  for(const child of app.doc.groups)if(child.parentId===id)child.parentId=g.parentId||null;
  app.doc.groups=app.doc.groups.filter(x=>x.id!==id)
 }
 app.selectedGroupIds=[];app.focusGroupId=null;commit();refreshLayers();refreshInspector();toast('Группа разгруппирована');
}
function isOneGroup(){if(app.selectedGroupIds?.length===1){const id=app.selectedGroupIds[0],members=groupMembers(id);return members.length===app.selectedIds.length&&members.every(m=>app.selectedIds.includes(m.id))}const a=picked(),g=a[0]?.groupId;return a.length>0&&g&&a.every(e=>e.groupId===g)&&groupMembers(g).length===a.length}
function toggleGroup(){if(isOneGroup())ungroupSelected();else groupSelected()}
// Clipboard stores the selected graph, including explicit group entities.
function selectedCanvasGraph(elements=picked(),inferGroups=false){
 const groupIds=[...(app.selectedGroupIds||[])];
 if(inferGroups){const ids=new Set(elements.map(e=>e.id));for(const g of app.doc.groups||[]){const members=groupMembers(g.id);if(members.length&&members.every(e=>ids.has(e.id)))groupIds.push(g.id)}}
 return selectCanvasGraph(app.doc,elements.map(e=>e.id),groupIds);
}
function appendCanvasGraph(source,offset=0,suffix=' копия',preserveExternal=true){
 const graph=remapCanvasGraph(source,uid,{selection:true,reservedIds:canvasGraphIds(app.doc),availableElementIds:preserveExternal?app.doc.elements.map(e=>e.id):[],availableGroupIds:preserveExternal?(app.doc.groups||[]).map(g=>g.id):[]});
 for(const g of graph.groups||[])g.name+=suffix;
 for(const e of graph.elements){e.x+=offset;e.y+=offset;e.name+=suffix}
 app.doc.groups.push(...(graph.groups||[]));
 const copiedIds=new Set(graph.elements.map(e=>e.id));
 for(const e of graph.elements){
  // A lone clipped copy must stay in the available base's stacking chain. The
  // renderer intentionally derives clipping from order; append would mask it
  // against an unrelated last layer despite a correct clipBaseId.
  const base=e.clipped&&!copiedIds.has(e.clipBaseId)?app.doc.elements.findIndex(item=>item.id===e.clipBaseId):-1;
  if(base>=0&&(app.doc.elements[base].groupId||null)===(e.groupId||null)){
   let at=base+1;while(at<app.doc.elements.length&&app.doc.elements[at].clipped&&(app.doc.elements[at].groupId||null)===(e.groupId||null))at++;
   app.doc.elements.splice(at,0,e);
  }else app.doc.elements.push(e);
 }
 return graph.elements.map(e=>e.id);
}
function copyLayers(){const a=picked();if(!a.length)return;app.layerClipboard={...selectedCanvasGraph(a),documentId:app.doc.id,slideId:app.doc.slides?.[app.doc.activeSlideIndex]?.id};toast('Скопировано слоёв: '+a.length)}
function pasteLayers(offset=24){if(!app.layerClipboard?.elements.length)return;const source=app.layerClipboard,sameCanvas=source.documentId===app.doc.id&&source.slideId===app.doc.slides?.[app.doc.activeSlideIndex]?.id;const ids=appendCanvasGraph(source,offset,' копия',sameCanvas);setSelected(ids,true);commit();toast('Вставлено слоёв: '+ids.length)}
function reorderLayer(sourceId,targetId,edge='before',sourceGroupId=null,targetGroupId=null){
 const all=app.doc.elements,sg=sourceGroupId||null,tg=targetGroupId||null;
 if(sg&&groupEffectiveLocked(groupInfo(sg)))return false;
 if(!sg&&isLayerLocked(all.find(e=>e.id===sourceId)))return false;
 if((sg&&tg&&groupAncestor(tg,sg))||(sg&&sg===tg))return false;
 const moving=sg?groupMembers(sg):all.filter(e=>e.id===sourceId);if(!moving.length)return false;
 const movingIds=new Set(moving.map(e=>e.id));
 const targetBlock=tg?groupMembers(tg):all.filter(e=>e.id===targetId);
 if(!tg&&movingIds.has(targetId))return false;
 const remaining=all.filter(e=>!movingIds.has(e.id));
 let pos=remaining.length;
 if(edge==='inside'&&tg){pos=remaining.findIndex(e=>e.groupId&&groupAncestor(e.groupId,tg));if(pos<0)pos=remaining.length;}
 else if(targetBlock.length){const tgt=targetBlock.filter(e=>!movingIds.has(e.id));if(!tgt.length)return false;const indices=tgt.map(e=>remaining.indexOf(e));pos=edge==='before'?Math.max(...indices)+1:Math.min(...indices)}
 remaining.splice(pos,0,...moving);app.doc.elements=remaining;
 const dest=edge==='inside'&&tg?tg:tg?(groupInfo(tg)?.parentId||null):(all.find(e=>e.id===targetId)?.groupId||null);
 if(sg){const g=groupInfo(sg);if(g)g.parentId=dest}
 else if(moving[0])moving[0].groupId=dest;
 for(const child of app.doc.elements)if(child.clipped){const base=findClipBase(app.doc,child);if(!base){child.clipped=false;delete child.clipBaseId}else child.clipBaseId=base.id}
 commit();refreshLayers();return true;
}
function layerRows(){
 const d=app.doc;ensureGroupData(d);
 const out=[],all=[...d.elements].reverse();
 const score=id=>{const members=groupMembers(id);return Math.max(-1,...members.map(e=>d.elements.indexOf(e)))};
 function walk(parent,depth){
  const items=[...d.groups.filter(g=>(g.parentId||null)===parent).map(g=>({kind:'group',groupId:g.id,score:score(g.id),name:g.name})),...all.filter(e=>(e.groupId||null)===parent).map(e=>({kind:'item',id:e.id,e,score:d.elements.indexOf(e)}))];
  items.sort((a,b)=>b.score-a.score);
  for(const item of items){out.push({...item,depth});if(item.kind==='group'&&!groupInfo(item.groupId).collapsed)walk(item.groupId,depth+1)}
 }
 walk(null,0);return out;
}
function layerThumbnail(e){
 try{
  const thumb=document.createElement('canvas');thumb.width=46;thumb.height=36;
  const c=thumb.getContext('2d');c.clearRect(0,0,46,36);
  c.fillStyle='#ffffff';c.fillRect(0,0,46,36);c.fillStyle='#e7e7eb';for(let y=0;y<36;y+=8)for(let x=0;x<46;x+=8)if((x/8+y/8)%2<1)c.fillRect(x,y,8,8);
  const b=boundsOf(e),w=Math.max(1,b.right-b.x),h=Math.max(1,b.bottom-b.y),scale=Math.min(42/w,32/h);
  c.setTransform(scale,0,0,scale,23-scale*(b.x+b.right)/2,18-scale*(b.y+b.bottom)/2);paintMaskedBase(c,e,app.doc);
  return thumb.toDataURL('image/png');
 }catch(err){return ''}
}
// Containers express hierarchy; rows keep a fixed local inset on both surfaces.
function renderLayerTree(renderRow){
 const rows=layerRows();let result='',open=0;
 for(const row of rows){
  while(open>row.depth){result+='</div></section>';open--}
  if(row.kind==='group'){
   const g=groupInfo(row.groupId),selected=(app.selectedGroupIds||[]).includes(g.id);
   result+=`<section class="layer-group ${selected?'selected-group':''}" data-group-container="${g.id}">${renderRow(row)}<div class="group-children" ${g.collapsed?'hidden':''}>`;open++;
  }else result+=renderRow(row);
 }
 while(open-- >0)result+='</div></section>';
 return result||'<div class="empty-state">Нет слоёв</div>';
}
function folderToggle(g){return `<button type="button" class="folder-toggle" data-folder-toggle="${g.id}" aria-expanded="${!g.collapsed}" aria-label="${g.collapsed?'Развернуть':'Свернуть'} группу" title="${g.collapsed?'Развернуть':'Свернуть'}">${uiIcon(g.collapsed?'chevronRight':'chevronDown')}</button>`}
function layerHTML(mobile=false){if(mobile)return mobileLayerHTML();return renderLayerTree(row=>{
 const group=row.kind==='group',e=row.e,g=group?groupInfo(row.groupId):null;
 const selected=group?(app.selectedGroupIds||[]).includes(row.groupId):app.selectedIds.includes(row.id);
 const maskBase=!group&&findClipBase(app.doc,e);
 const effectiveVisible=group?groupEffectiveVisible(g):isLayerVisible(e);
 const effectiveLocked=group?groupEffectiveLocked(g):isLayerLocked(e);
 const icon=group?uiIcon('folder'):e?`<img draggable="false" src="${layerThumbnail(e)}" alt="">`:'';
 return `<div class="${mobile?'mobile-layer':'layer'} layer-sort ${selected?'selected active':''} ${group?'group-row':''} ${e?.clipped?'clipped-row':''} ${!effectiveVisible?'tree-hidden':''} ${effectiveLocked?'tree-locked':''}" style="--depth:${row.depth}" data-layer="${group?'':row.id}" data-sort="${group?row.groupId:row.id}" ${group?`data-group-id="${row.groupId}"`:''} draggable="false">
  ${!group&&e.clipped&&maskBase?`<span class="clip-tag" title="Обтравочная маска">↳</span>`:''}
  ${group?folderToggle(g):''}
  <span class="layer-symbol layer-thumb ${group?'folder-icon':''} ${!group&&app.maskEditId!==e.id&&selected?'layer-image-active':''}" ${!group?`data-select-layer-thumb="${e.id}" title="Редактировать содержимое слоя"`:``}>${icon}</span>${!group&&e.layerMaskSrc?`<span class="layer-mask-link" title="Связь слоя и маски">♧</span><button type="button" class="layer-mask-thumb ${app.maskEditId===e.id?'active':''}" data-select-mask="${e.id}" title="Выбрать маску · повторный клик — удалить маску"><img src="${e.layerMaskSrc}" alt="Маска"></button>`:''}
  ${mobile?`<span class="mobile-drag-handle" title="Перетащить слой" aria-label="Перетащить слой">⠿</span>`:''}<span class="layer-name" data-rename="${group?g.id:e.id}" title="Двойной клик — переименовать">${html(group?g.name:e.name)}</span>
  <span class="layer-actions">${!group?`<button type="button" class="layer-mask-create" data-create-mask="${e.id}" title="${e.layerMaskSrc?'Редактировать маску':'Добавить маску слоя'}" aria-label="Добавить маску слоя">◩</button>`:''}${!group&&e?.type==='text'?`<button type="button" class="layer-title-button ${e.isTitleLayer?'active':''}" data-title-toggle="${e.id}" aria-pressed="${e.isTitleLayer?'true':'false'}" title="Использовать как заголовок карточки" aria-label="Использовать как заголовок карточки">H1</button>${e.isTitleLayer&&app.doc.type==='card'&&app.doc.hasCustomName?`<button type="button" class="layer-title-button" data-reset-autoname="true" title="Вернуть автоматическое название карточки" aria-label="Вернуть автоматическое название карточки">↻</button>`:''}`:''}<button type="button" data-layeract="visibility" data-kind="${group?'group':'layer'}" data-id="${group?g.id:e.id}" title="${effectiveVisible?'Скрыть':'Показать'} ${group?'группу':'слой'}" aria-label="${effectiveVisible?'Скрыть':'Показать'} ${group?'группу':'слой'}">${uiIcon(effectiveVisible?'eye':'eyeOff')}</button><button type="button" data-layeract="lock" data-kind="${group?'group':'layer'}" data-id="${group?g.id:e.id}" title="${effectiveLocked?'Разблокировать':'Заблокировать'} ${group?'группу':'слой'}" aria-label="${effectiveLocked?'Разблокировать':'Заблокировать'} ${group?'группу':'слой'}">${uiIcon(effectiveLocked?'lock':'unlock')}</button></span>
  ${!group&&findClipBase(app.doc,e)?`<span class="layer-clip-hit" data-clip-layer="${e.id}" title="Alt+клик — ${e.clipped?'снять':'создать'} обтравочную маску"></span>`:''}
 </div>`})}

// v0.40: Mobile rows use the same layerRows / group entities as desktop.
const mobileLayerChoice=new Set();let mobileLayerMulti=false;
function mobileLayerKey(row){return row.kind==='group'?'g:'+row.groupId:'l:'+row.id}
function mobileLayerHTML(){return renderLayerTree(row=>{
 const group=row.kind==='group',g=group?groupInfo(row.groupId):null,e=row.e;
 const id=group?row.groupId:row.id,key=mobileLayerKey(row);
 const selected=mobileLayerMulti?mobileLayerChoice.has(key):(group?(app.selectedGroupIds||[]).includes(id):app.selectedIds.includes(id));
 const shown=group?groupEffectiveVisible(g):isLayerVisible(e),locked=group?groupEffectiveLocked(g):isLayerLocked(e);
 const icon=group?uiIcon('folder'):`<img draggable="false" src="${layerThumbnail(e)}" alt="">`;
 return `<div class="mobile-layer layer-sort ${selected?'selected active':''} ${group?'group-row':''} ${locked?'tree-locked':''} ${!shown?'tree-hidden':''}" data-sort="${id}" ${group?`data-group-id="${id}"`:`data-layer="${id}"`} style="--depth:${row.depth}" draggable="false">
 ${mobileLayerMulti?`<input class="mobile-layer-check" type="checkbox" data-mobile-select="${key}" ${selected?'checked':''} aria-label="Выбрать ${html(group?g.name:e.name)}">`:''}${group?folderToggle(g):''}
 <span class="layer-symbol layer-thumb ${group?'folder-icon':''}">${icon}</span>
 ${!mobileLayerMulti?'<span class="mobile-drag-handle" aria-label="Перетащить слой" title="Перетащить слой">⠿</span>':''}
 <span class="layer-name" data-rename="${id}">${html(group?g.name:e.name)}</span>
 ${!mobileLayerMulti?`<span class="layer-actions"><button type="button" data-layeract="visibility" data-kind="${group?'group':'layer'}" data-id="${id}" title="${shown?'Скрыть':'Показать'}">${uiIcon(shown?'eye':'eyeOff')}</button><button type="button" data-layeract="lock" data-kind="${group?'group':'layer'}" data-id="${id}" title="${locked?'Разблокировать':'Заблокировать'}">${uiIcon(locked?'lock':'unlock')}</button><button type="button" class="mobile-layer-more" data-mobile-layer-menu="${key}" title="Действия со слоем" aria-label="Действия со слоем">⋯</button></span>`:''}
 </div>`})}
function mobileSelectionUI(){const choose=$('#mobileLayersSelect'),bar=$('#mobileLayerMultiActions');if(!choose||!bar)return;
 choose.classList.toggle('active',mobileLayerMulti);choose.textContent=mobileLayerMulti?'Готово':'Выбрать';bar.classList.toggle('hidden',!mobileLayerMulti);
 if(!mobileLayerMulti)return;
 const n=mobileLayerChoice.size;bar.innerHTML=`<span class="mobile-selected-counter">${n} выбрано</span><button type="button" data-multi-action="all">Все</button><button type="button" data-multi-action="clear">Снять</button><button type="button" data-multi-action="group" ${n<2?'disabled':''}>Группа</button><button type="button" data-multi-action="ungroup" ${![...mobileLayerChoice].some(x=>x.startsWith('g:'))?'disabled':''}>Разгрупп.</button>`;
}
function closeMobileLayerMenu(){const menu=$('#mobileLayerActionMenu');if(menu){menu.classList.add('hidden');menu.dataset.key=''}}
function mobileGroupSelection(){const groups=[...mobileLayerChoice].filter(k=>k.startsWith('g:')).map(k=>k.slice(2));const ids=[...mobileLayerChoice].filter(k=>k.startsWith('l:')).map(k=>k.slice(2));
 // Never accidentally include unrelated siblings via automatic group expansion.
 const all=[...ids,...groups.flatMap(id=>groupMembers(id).map(e=>e.id))];setSelected([...new Set(all)],true);app.selectedGroupIds=groups;app.focusGroupId=groups.length===1?groups[0]:null;return {groups,ids};
}
function exitMobileLayerMulti(){mobileLayerMulti=false;mobileLayerChoice.clear();closeMobileLayerMenu();mobileSelectionUI();renderMobileLayers()}
function deleteLayerOrGroup(key){const group=key.startsWith('g:'),id=key.slice(2);
 if(group){const g=groupInfo(id);if(!g)return;const members=groupMembers(id);if(members.length&&!confirm(`Удалить группу «${g.name}» и ${members.length} вложенных слоёв?`))return;
  const nested=new Set(groupDescendantIds(id));nested.add(id);app.doc.elements=app.doc.elements.filter(e=>!e.groupId||!nested.has(e.groupId));app.doc.groups=app.doc.groups.filter(g=>!nested.has(g.id));setSelected([]);commit('Удаление группы');}
 else{if(!app.doc.elements.some(e=>e.id===id))return;setSelected([id],true);deleteElement(true)}
 mobileLayerChoice.delete(key);closeMobileLayerMenu();refreshLayers();refreshInspector();mobileSelectionUI();}
function openMobileLayerMenu(key,trigger){const menu=$('#mobileLayerActionMenu');if(!menu)return;const group=key.startsWith('g:'),id=key.slice(2),g=group?groupInfo(id):null,e=group?null:app.doc.elements.find(e=>e.id===id);if(!g&&!e)return;
 if(!menu.classList.contains('hidden')&&menu.dataset.key===key){closeMobileLayerMenu();return}
 menu.dataset.key=key;
 const opts=[];if(!group&&e.type==='text')opts.push(['title',e.isTitleLayer?'Убрать статус заголовка':'Сделать заголовком','heading']);
 if(!group)opts.push(['mask',e.layerMaskSrc?'Удалить маску':'Добавить маску','mask']);
 if(group)opts.push(['ungroup','Разгруппировать','layers']);
 opts.push(['rename','Переименовать','edit']);
 if(mobileLayerChoice.size>1)opts.push(['group','Сгруппировать выбранные','folder']);
 opts.push(['delete','Удалить','trash']);
 menu.innerHTML=opts.map(([act,title,icon])=>`<button type="button" data-mobile-layer-action="${act}" data-mobile-target="${key}" ${act==='delete'?'class="danger"':''}>${uiIcon(icon)}<span>${title}</span></button>`).join('');
 menu.classList.remove('hidden');menu.style.visibility='hidden';
 const r=trigger.getBoundingClientRect(),height=menu.offsetHeight,width=menu.offsetWidth;
 menu.style.left=Math.max(8,Math.min(innerWidth-width-8,r.right-width))+'px';
 menu.style.top=(r.bottom+height+8<innerHeight? r.bottom+4 : Math.max(8,r.top-height-4))+'px';menu.style.visibility='';}
function mobileLayerAction(key,action){const group=key.startsWith('g:'),id=key.slice(2),e=app.doc.elements.find(e=>e.id===id);closeMobileLayerMenu();
 if(action==='delete'){deleteLayerOrGroup(key);return}
 if(action==='rename'){const row=[...$('#mobileLayerList').querySelectorAll('.layer-sort')].find(x=>x.dataset.sort===id);const el=row?.querySelector('[data-rename]');if(el)renameLayerFromName(el);return}
 if(action==='title'&&e?.type==='text'){const next=!e.isTitleLayer;for(const el of app.doc.elements)if(el.type==='text')el.isTitleLayer=false;e.isTitleLayer=next;syncAutoCardTitle();commit('Назначение заголовка карточки');refreshLayers();refreshInspector();return}
 if(action==='mask'&&e){if(e.layerMaskSrc)removeLayerMask(id);else addLayerMask(id);refreshLayers();return}
 if(action==='ungroup'&&group){setSelected(groupMembers(id).map(x=>x.id),true);app.selectedGroupIds=[id];app.focusGroupId=id;ungroupSelected();refreshLayers();return}
 if(action==='group'){mobileGroupSelection();if(groupSelected())exitMobileLayerMulti();return}
}
function onMobileMultiAction(action){if(action==='all'){for(const row of layerRows())mobileLayerChoice.add(mobileLayerKey(row));renderMobileLayers();return}
 if(action==='clear'){mobileLayerChoice.clear();renderMobileLayers();return}
 if(action==='group'){if(mobileLayerChoice.size<2)return;mobileGroupSelection();if(groupSelected())exitMobileLayerMulti();else renderMobileLayers();return}
 if(action==='ungroup'){const ids=[...mobileLayerChoice].filter(k=>k.startsWith('g:')).map(k=>k.slice(2));if(!ids.length)return;const layers=[...new Set(ids.flatMap(id=>groupMembers(id).map(e=>e.id)))];setSelected(layers,true);app.selectedGroupIds=ids;app.focusGroupId=ids.length===1?ids[0]:null;ungroupSelected();exitMobileLayerMulti()}
}
function active(){return app.doc?.elements.find(e=>e.id===app.selected)||null}
