 const state=saveState(rec.id),key=JSON.stringify(rec);
 if(state.pending?.key===key)return state.pending.promise;
 if(!state.pending&&state.saved===key){state.error=null;if(app.doc?.id===rec.id)refreshSaveStatus();return true}
 const previous=state.pending,sequence=++state.sequence,pending={key,promise:null};
 state.pending=pending;
 pending.promise=(async()=>{
  try{
   if(previous)await previous.promise;
   // Recheck after the queue: a workspace replacement / deletion may have begun.
   if(replacementSealed||rec.projectId===deletingProjectId||deletedProjectIds.has(rec.projectId)||documentSaves.get(rec.id)!==state)return false;
   if(state.saved!==key){
    await dbOp('docs','readwrite',s=>s.put(rec));
    confirmDocument(rec);state.saved=key;state.confirmed=sequence;
   }
   state.error=null;return true;
  }catch(error){state.error=error;return false}
  finally{if(state.pending===pending)state.pending=null;if(app.doc?.id===rec.id)refreshSaveStatus()}
 })();
 // The workspace barrier must include queued snapshots, not just issued IDB work.
 workspaceBarrier.track(pending.promise,{store:'docs',write:true});
