 const previous=rasterCache.get(e.rasterSrc)||getImage(e.rasterSrc);if(previous)c.drawImage(previous,0,0,cv.width,cv.height);
 c.fillStyle=color;if(app.pixelSelection?.mask){c.save();const filled=document.createElement('canvas');filled.width=cv.width;filled.height=cv.height;const f=filled.getContext('2d');f.fillStyle=color;f.fillRect(0,0,cv.width,cv.height);f.globalCompositeOperation='destination-in';f.drawImage(app.pixelSelection.mask,0,0);c.drawImage(filled,0,0);c.restore()}
 else c.fillRect(0,0,cv.width,cv.height);
