function currentPaintLayer(){
 const selected=active();if(app.maskEditId)return null;
 if(selected&&!isLayerLocked(selected)&&selected.type==='raster')return selected;
 if(selected&&!isLayerLocked(selected)&&(selected.type==='image'||selected.fillType==='image')&&selected.imageSrc){
  if(!getImage(selected.imageSrc)){toast('Изображение ещё загружается — повтори мазок через мгновение');return null}
  // Flatten displayed image into its existing layer once; subsequent brush strokes edit the same pixels.
  const d=app.doc,cv=document.createElement('canvas');cv.width=d.width;cv.height=d.height;paintElement(cv.getContext('2d'),selected);
  const src=cv.toDataURL('image/png');rememberRaster(src,cv);
  Object.assign(selected,{type:'raster',x:0,y:0,w:d.width,h:d.height,rotation:0,opacity:100,flipX:false,flipY:false,fillType:'none',strokeWidth:0,imageSrc:'',rasterSrc:src});
  refreshLayers();return selected;
 }
 return newRasterLayer({commitNow:false});
}
