function deleteElement(force=false){if(!app.selectedIds.length)return;const deletable=new Set(picked().filter(e=>force||!isLayerLocked(e)).map(e=>e.id));if(!deletable.size)return;app.doc.elements=app.doc.elements.filter(e=>!deletable.has(e.id));setSelected([]);commit('Удаление слоя');refreshLayers();refreshInspector()}

