function layerInteraction(root){
 let lastRenameDown=null,renamingUntil=0;
 // A rename double click must be consecutive: inspector, history and layer
 // controls interrupt it, even when the same name is clicked again within 540 ms.
 document.addEventListener('pointerdown',ev=>{
  if(!root.contains(ev.target)||!ev.target.closest('[data-rename]'))lastRenameDown=null;
 },true);
 root.addEventListener('pointerdown',ev=>{if(root.id==='mobileLayerList'&&(mobileLayerMulti||ev.pointerType==='touch'))return;const n=ev.target.closest('[data-rename]');if(!n)return;const id=n.dataset.rename,now=performance.now();if(lastRenameDown?.id===id&&now-lastRenameDown.time<540){ev.preventDefault();ev.stopPropagation();renamingUntil=now+600;renameLayerFromName(n);lastRenameDown=null;return}lastRenameDown={id,time:now}},true);
 root.addEventListener('dblclick',ev=>{const name=ev.target.closest('[data-rename]');if(name){ev.preventDefault();renameLayerFromName(name)}});
 root.addEventListener('click',ev=>{
   if(root.id==='mobileLayerList'){const menuButton=ev.target.closest('[data-mobile-layer-menu]');if(menuButton){ev.stopPropagation();openMobileLayerMenu(menuButton.dataset.mobileLayerMenu,menuButton);return;}if(mobileLayerMulti&&!ev.target.closest('[data-folder-toggle]')){if(ev.target.closest('button, .mobile-drag-handle'))return;const row=ev.target.closest('.layer-sort');if(row){const key=row.dataset.groupId?'g:'+row.dataset.groupId:'l:'+row.dataset.layer;if(mobileLayerChoice.has(key))mobileLayerChoice.delete(key);else mobileLayerChoice.add(key);renderMobileLayers();}return;}}
  if(ev.target.closest('.layer-rename-input')||root.querySelector('.layer-rename-input'))return;
  const folder=ev.target.closest('[data-folder-toggle]');if(folder){const g=groupInfo(folder.dataset.folderToggle);if(g){g.collapsed=!g.collapsed;commit();refreshLayers()}return}
  const clip=ev.target.closest('[data-clip-layer]');if(clip&&ev.altKey){ev.preventDefault();toggleClip(clip.dataset.clipLayer);return}
  if(ev.target.closest('[data-reset-autoname]')){ev.preventDefault();ev.stopPropagation();app.doc.hasCustomName=false;syncAutoCardTitle();commit('Возврат автоназвания');refreshLayers();refreshInspector();return}
  const toggle=ev.target.closest('[data-title-toggle]');if(toggle){
   ev.preventDefault();ev.stopPropagation();const el=app.doc?.elements.find(o=>o.id===toggle.dataset.titleToggle);if(!el||el.type!=='text')return;
   const next=!el.isTitleLayer;for(const other of app.doc.elements)if(other.type==='text')other.isTitleLayer=false;el.isTitleLayer=next;
   syncAutoCardTitle();commit('Назначение заголовка карточки');refreshLayers();refreshInspector();return;
  }
  const addmask=ev.target.closest('[data-create-mask]');if(addmask){ev.stopPropagation();addLayerMask(addmask.dataset.createMask);return}
  const selectmask=ev.target.closest('[data-select-mask]');if(selectmask){ev.stopPropagation();const id=selectmask.dataset.selectMask;if(app.maskEditId===id){removeLayerMask(id);return}app.maskEditId=id;setSelected([id],true);inkRefreshColor();return}
  const selectlayer=ev.target.closest('[data-select-layer-thumb]');if(selectlayer){ev.stopPropagation();app.maskEditId=null;setSelected([selectlayer.dataset.selectLayerThumb],true);inkRefreshColor();return}
  const act=ev.target.closest('[data-layeract]');if(act){
   ev.preventDefault();ev.stopPropagation();
   const obj=act.dataset.kind==='group'?groupInfo(act.dataset.id):app.doc.elements.find(x=>x.id===act.dataset.id);
   if(!obj)return;
   const k=act.dataset.layeract==='visibility'?'visible':'locked';if(k==='visible')obj.visible=obj.visible===false;else obj.locked=obj.locked!==true;
   commit(k==='visible'?(obj.visible?'Показ группы/слоя':'Скрытие группы/слоя'):(obj.locked?'Блокировка группы/слоя':'Разблокировка группы/слоя'));
   refreshLayers();refreshInspector();refreshMobileTools();return;
  }
  const row=ev.target.closest('.layer-sort');if(!row)return;
  if(row.dataset.groupId)selectGroup(row.dataset.groupId,ev.shiftKey||ev.ctrlKey||ev.metaKey||app.multiMode);
  else {const prev=ev.shiftKey||ev.ctrlKey||ev.metaKey||app.multiMode?[...(app.selectedGroupIds||[])]:[];select(row.dataset.layer,ev.shiftKey||ev.ctrlKey||ev.metaKey||app.multiMode,true);app.selectedGroupIds=prev;app.focusGroupId=prev.length===1?prev[0]:null;refreshLayers()}
 })
}
