// Drag layers between rows. A layer can be moved to the top by dropping below the last row.
function wireLayerReorder(root){
 let drag=null,raf=0;
 function clean(){if(drag?.holdTimer)clearTimeout(drag.holdTimer);cancelAnimationFrame(raf);raf=0;root.classList.remove('layer-reordering');root.querySelectorAll('.layer-sort').forEach(r=>r.classList.remove('sorting','sort-before','sort-after','sort-inside'));drag=null}
 function updateTarget(x,y){if(!drag)return;const rows=[...root.querySelectorAll('.layer-sort')];if(!rows.length)return;
  const area=root.getBoundingClientRect();let row=rows.find(r=>{const b=r.getBoundingClientRect();return y>=b.top&&y<=b.bottom})||(y<area.top?rows[0]:rows[rows.length-1]);
  const b=row.getBoundingClientRect();drag.target=row.dataset.sort;drag.targetGroup=row.dataset.groupId||null;
  drag.edge=row.dataset.groupId&&x>b.left+75&&y>b.top+b.height*.23&&y<b.bottom-b.height*.77?'inside':y<b.top+b.height/2?'before':'after';
  rows.forEach(r=>{r.classList.toggle('sort-before',r===row&&drag.edge==='before');r.classList.toggle('sort-after',r===row&&drag.edge==='after');r.classList.toggle('sort-inside',r===row&&drag.edge==='inside')});
 }
 function autoScroll(){if(!drag)return;if(!drag.ready||!drag.moved){raf=requestAnimationFrame(autoScroll);return}const b=root.getBoundingClientRect(),m=45;const speed=drag.y<b.top+m?-Math.min(16,(b.top+m-drag.y)*.5):drag.y>b.bottom-m?Math.min(16,(drag.y-(b.bottom-m))*.5):0;
  if(speed){root.scrollTop+=speed;updateTarget(drag.x,drag.y)}raf=requestAnimationFrame(autoScroll)}
 root.addEventListener('pointerdown',ev=>{if(ev.button!==0||ev.altKey||(root.id==='mobileLayerList'&&mobileLayerMulti)||ev.target.closest('button,input,.layer-actions,.layer-rename-input,[data-clip-layer]'))return;
  const row=ev.target.closest('.layer-sort');if(!row)return;const grip=!!ev.target.closest('.mobile-drag-handle');drag={id:row.dataset.sort,sourceGroup:row.dataset.groupId||null,pointerId:ev.pointerId,startX:ev.clientX,startY:ev.clientY,x:ev.clientX,y:ev.clientY,prevY:ev.clientY,moved:false,target:null,edge:'before',ready:ev.pointerType!=='touch'||grip,pointerType:ev.pointerType};
  // Touch gestures on a row belong to native scrolling; drag starts only on the handle.
  if(ev.pointerType==='touch'&&!grip){drag=null;return;}
  if(grip){ev.preventDefault();try{ev.target.setPointerCapture(ev.pointerId)}catch{}}
  raf=requestAnimationFrame(autoScroll);
 });
 window.addEventListener('pointermove',ev=>{if(!drag||ev.pointerId!==drag.pointerId)return;drag.x=ev.clientX;drag.y=ev.clientY;
  if(drag.pointerType==='touch'&&!drag.ready){if(Math.hypot(ev.clientX-drag.startX,ev.clientY-drag.startY)>8){drag.scrolling=true;clearTimeout(drag.holdTimer)}drag.prevY=ev.clientY;return;}
  if(!drag.moved&&Math.hypot(ev.clientX-drag.startX,ev.clientY-drag.startY)>7){drag.moved=true;root.classList.add('layer-reordering');root.querySelector(`[data-sort="${drag.id}"]`)?.classList.add('sorting')}
  if(drag.moved){updateTarget(drag.x,drag.y);ev.preventDefault()}
 },{passive:false});
 window.addEventListener('pointerup',ev=>{if(!drag||ev.pointerId!==drag.pointerId)return;const {id,target,edge,moved,sourceGroup,targetGroup,ready}=drag;clean();if(ready&&moved&&target)reorderLayer(id,target,edge,sourceGroup,targetGroup)},true);
 window.addEventListener('pointercancel',ev=>{if(drag&&drag.pointerId===ev.pointerId)clean()},true);
}
wireLayerReorder($('#layers'));wireLayerReorder($('#mobileLayerList'));

