function selectionCombine(incoming,mode,point=null,label=null){const prev=app.pixelSelection?.data;if(mode==='subtract'&&!prev)return;if(mode==='replace'||!prev||prev.length!==incoming.length){selectionSet(incoming,point);commit(label||'Выделение области');return}const output=new Uint8Array(incoming.length);for(let i=0;i<output.length;i++)output[i]=mode==='add'?(prev[i]|incoming[i]):(prev[i]&&!incoming[i]?255:0);selectionSet(output,point);commit(label||(mode==='add'?'Добавление к выделению':'Вычитание из выделения'))}
