function createSeriesSlide(blank=true,template=null){const d=app.doc;if(d?.type!=='card')return;syncCurrentSlide(d);let slide;
 if(blank){const next=newDoc({title:d.title,width:d.width,height:d.height,type:'card'});slide=makeSlideFromDoc(next)}
 else{slide=makeTemplateSlide(template);slide.createdAt=Date.now()}
 d.slides.push(slide);changeSlide(d.slides.length-1);saveSoon();$('#slideAddMenu').classList.add('hidden')
}
async function removeSeriesSlide(index){const d=app.doc;if(d?.type!=='card'||d.slides.length<=1)return;if(!confirm(`Удалить холст ${index+1} из серии? Это действие нельзя отменить после сохранения.`))return;syncCurrentSlide(d);d.slides.splice(index,1);const target=Math.min(index===d.activeSlideIndex?index:d.activeSlideIndex-(index<d.activeSlideIndex?1:0),d.slides.length-1);applySlideToRoot(d,target);setSelected([],true);resetHistory();fitCanvas();renderSlideStrip();commit();toast('Холст удалён')}
