function arrangeLayer(mode){const chosen=new Set(app.selectedIds);if(!chosen.size)return;const rest=app.doc.elements.filter(e=>!chosen.has(e.id)),a=app.doc.elements.filter(e=>chosen.has(e.id));let target=0;
 if(mode==='front')app.doc.elements=[...rest,...a];else if(mode==='back')app.doc.elements=[...a,...rest];else{let indexes=app.doc.elements.map((e,i)=>chosen.has(e.id)?i:-1).filter(i=>i>=0);const index=mode==='forward'?Math.min(app.doc.elements.length-a.length,Math.max(...indexes)+1):Math.max(0,Math.min(...indexes)-1);rest.splice(index,0,...a);app.doc.elements=rest}commit();refreshLayers()}
function alignPicked(action){const es=picked().filter(e=>!e.locked);if(!es.length)return;const bounds=selectionBounds(),doc=app.doc;if(es.length===1){const e=es[0];if(e.type==='text'){if(['left','hcenter','right'].includes(action))e.textAlign={left:'left',hcenter:'center',right:'right'}[action];else e.verticalAlign={top:'top',vcenter:'middle',bottom:'bottom'}[action];commit();refreshInspector();return}if(e.fillType==='image'){const g=imageGeometry(e);if(g){const ox=Math.max(0,(g.dw-e.w)/2)/e.w*100,oy=Math.max(0,(g.dh-e.h)/2)/e.h*100;if(['left','hcenter','right'].includes(action))e.cropX={left:ox,hcenter:0,right:-ox}[action];else e.cropY={top:oy,vcenter:0,bottom:-oy}[action];commit();refreshInspector()}return}toast('Выравнивание внутри рамки доступно для текста и фото');return}for(const e of es){const B=boundsOf(e);let dx=0,dy=0;const area=es.length===1?{x:0,y:0,right:doc.width,bottom:doc.height}:bounds;
 if(action==='left')dx=area.x-B.x;if(action==='right')dx=area.right-B.right;if(action==='hcenter')dx=(area.x+area.right-B.x-B.right)/2;
 if(action==='top')dy=area.y-B.y;if(action==='bottom')dy=area.bottom-B.bottom;if(action==='vcenter')dy=(area.y+area.bottom-B.y-B.bottom)/2;
 e.x=fmt(e.x+dx);e.y=fmt(e.y+dy);
 }commit();refreshInspector()}
function contextAction(key){const es=picked();if(key==='delete-guide'){if(app.contextGuide>=0){app.doc.rulers.splice(app.contextGuide,1);app.contextGuide=-1;commit();toast('Направляющая удалена')}}else if(key==='saveShape')openSaveSelectedShape();else if(key==='replaceImage'){const e=active();if(e&&(e.type==='image'||e.fillType==='image')){app.pendingImage={kind:'replace',id:e.id};$('#imageInput').click()}}else if(key==='titleLayer'){const e=active();if(e?.type==='text'){const next=!e.isTitleLayer;for(const el of app.doc.elements)if(el.type==='text')el.isTitleLayer=false;e.isTitleLayer=next;syncAutoCardTitle();commit('Заголовок карточки');refreshLayers();refreshInspector()}}else if(key==='copy')copyLayers();else if(key==='paste')pasteLayers();else if(key==='delete')deleteElement();else if(key==='lock'){const value=!es.every(x=>x.locked);es.forEach(x=>x.locked=value);commit();refreshLayers();refreshInspector()}
 else if(['front','back','forward','backward'].includes(key))arrangeLayer(key);
 else if(['left','right','top','bottom','hcenter','vcenter'].includes(key))alignPicked(key);
 else if(key==='flipH'||key==='flipV'){for(const e of es){e[key==='flipH'?'flipX':'flipY']=!e[key==='flipH'?'flipX':'flipY']}commit()}
 hideContextMenu()}
