// v0.20: unified stage with several artboards and docked slide navigation.
const ARTBOARD_GAP=105, ARTBOARD_MARGIN=74;
let artboardPreviewBusy=false;
function isArtboardSeries(){return !!(app.doc&&app.doc.type==='card'&&Array.isArray(app.doc.slides))}
function seriesSceneDimensions(z=app.zoom){const d=app.doc;const slides=d?.slides||[];const gap=Math.max(38,ARTBOARD_GAP*z);const widths=slides.map(s=>s.width*z);const height=Math.max(0,...slides.map(s=>s.height*z));const content=widths.reduce((a,b)=>a+b,0)+gap*Math.max(0,slides.length-1);return {gap,widths,height,content,sceneW:content+2*ARTBOARD_MARGIN,sceneH:height+160};}
function seriesLocations(z=app.zoom){const d=app.doc,geometry=seriesSceneDimensions(z),list=[];let x=ARTBOARD_MARGIN;for(let i=0;i<d.slides.length;i++){const slide=d.slides[i];list.push({x,y:80,w:slide.width*z,h:slide.height*z,index:i});x+=slide.width*z+geometry.gap}return {list,geometry}}
function drawBoardCanvas(canvasEl,sd){const scale=Math.min(1,Math.sqrt(2600000/Math.max(1,sd.width*sd.height)));canvasEl.width=Math.max(1,Math.round(sd.width*scale));canvasEl.height=Math.max(1,Math.round(sd.height*scale));const c=canvasEl.getContext('2d');c.setTransform(canvasEl.width/sd.width,0,0,canvasEl.height/sd.height,0,0);paintDocument(c,sd,false)}
