function fitCanvas(){if(!app.doc)return;const area=$('#stageScroller');if(isArtboardSeries()){const d=app.doc;ensureCardSlides(d);const total=d.slides.reduce((s,slide)=>s+slide.width,0)+ARTBOARD_GAP*Math.max(0,d.slides.length-1);const mh=Math.max(...d.slides.map(slide=>slide.height));const narrow=window.matchMedia('(max-width:760px)').matches;const margin=narrow?8:90;app.zoom=narrow?clamp(Math.min((area.clientWidth-margin*2)/d.width,(area.clientHeight-margin*2-16)/d.height),.04,3):clamp(Math.min((area.clientWidth-180)/total,(area.clientHeight-175)/mh),.04,3);app.lastZoom=app.zoom;applyZoom();requestAnimationFrame(()=>seriesFocus(d.activeSlideIndex));return}
 const viewport=$('#stageViewport');viewport.classList.remove('multi-artboard');viewport.style.width='';viewport.style.height='';$('#canvasHost').style.left='';$('#canvasHost').style.top='';$('#canvasHost').style.width='';$('#canvasHost').style.height='';const mobile=matchMedia('(max-width:760px)').matches,gutter=mobile?8:34;const maxW=Math.max(80,area.clientWidth-gutter*2),maxH=Math.max(80,area.clientHeight-gutter*2);app.zoom=clamp(Math.min(maxW/app.doc.width,maxH/app.doc.height),.04,3);app.lastZoom=app.zoom;applyZoom();if(mobile)requestAnimationFrame(()=>{area.scrollLeft=Math.max(0,(area.scrollWidth-area.clientWidth)/2);area.scrollTop=Math.max(0,(area.scrollHeight-area.clientHeight)/2)})}
function applyZoom(anchor){if(!app.doc)return;const d=app.doc,stage=$('#stageScroller'),old=app.lastZoom||app.zoom;
 if(isArtboardSeries()){ensureCardSlides(d);const r=stage.getBoundingClientRect();const target=anchor||{x:r.left+stage.clientWidth/2,y:r.top+stage.clientHeight/2};const screenX=target.x-r.left,screenY=target.y-r.top;const worldX=(stage.scrollLeft+screenX-ARTBOARD_MARGIN)/old,worldY=(stage.scrollTop+screenY-80)/old;
 const ratio=Math.min(devicePixelRatio||1,8192/(d.width*app.zoom),8192/(d.height*app.zoom),Math.sqrt(23000000/(d.width*d.height*app.zoom*app.zoom)));app.renderScale=ratio;canvas.style.width=Math.max(1,d.width*app.zoom)+'px';canvas.style.height=Math.max(1,d.height*app.zoom)+'px';canvas.width=Math.max(1,Math.round(d.width*app.zoom*ratio));canvas.height=Math.max(1,Math.round(d.height*app.zoom*ratio));app.lastZoom=app.zoom;
 $('#zoomLabel').textContent=Math.round(app.zoom*100)+'%';redrawSeriesWorkspace();positionInlineText();renderRulers();stage.scrollLeft=Math.max(0,ARTBOARD_MARGIN+worldX*app.zoom-screenX);stage.scrollTop=Math.max(0,80+worldY*app.zoom-screenY);paint();return;}
 const ratio=Math.min(devicePixelRatio||1,8192/(d.width*app.zoom),8192/(d.height*app.zoom),Math.sqrt(24000000/(d.width*d.height*app.zoom*app.zoom))),rect=canvas.getBoundingClientRect(),pointer=anchor||{x:stage.getBoundingClientRect().left+stage.clientWidth/2,y:stage.getBoundingClientRect().top+stage.clientHeight/2};app.renderScale=ratio;const dx=(pointer.x-rect.left)/old,dy=(pointer.y-rect.top)/old;app.lastZoom=app.zoom;canvas.style.width=Math.max(1,d.width*app.zoom)+'px';canvas.style.height=Math.max(1,d.height*app.zoom)+'px';canvas.width=Math.max(1,Math.round(d.width*app.zoom*ratio));canvas.height=Math.max(1,Math.round(d.height*app.zoom*ratio));$('#zoomLabel').textContent=Math.round(app.zoom*100)+'%';positionInlineText();updateQuickBubble();requestAnimationFrame(renderRulers);if(Math.abs(old-app.zoom)>.0001){const after=canvas.getBoundingClientRect();stage.scrollLeft+=(after.left+dx*app.zoom-pointer.x);stage.scrollTop+=(after.top+dy*app.zoom-pointer.y)}paint()}

// Presets set width and height atomically; manually typed dimensions remain unrestricted.
function applyCanvasPreset(container,code){
 const series=container.id==='seriesCreateDialog';
 const width=document.getElementById(series?'seriesNewWidth':'newDocW');
 const height=document.getElementById(series?'seriesNewHeight':'newDocH');
 const dims=code==='current'?[app.doc?.width||1080,app.doc?.height||1350]:code.split('x').map(Number);
 if(!Number.isFinite(dims[0])||!Number.isFinite(dims[1]))return;
 width.value=String(dims[0]);height.value=String(dims[1]);
 updateCanvasPresetSelection(container);
 width.dispatchEvent(new Event('input',{bubbles:true}));height.dispatchEvent(new Event('input',{bubbles:true}));
}
function updateCanvasPresetSelection(container){
 const series=container.id==='seriesCreateDialog';
 const w=Number(document.getElementById(series?'seriesNewWidth':'newDocW').value);
 const h=Number(document.getElementById(series?'seriesNewHeight':'newDocH').value);
 container.querySelectorAll('[data-preset-size]').forEach(btn=>{
  const code=btn.dataset.presetSize;
  const pair=code==='current'?[app.doc?.width||1080,app.doc?.height||1350]:code.split('x').map(Number);
  btn.classList.toggle('selected',w===pair[0]&&h===pair[1]);
 });
}
for(const id of ['seriesCreateDialog','sizeDialog']){
 const modal=document.getElementById(id);
 modal.addEventListener('click',e=>{const btn=e.target.closest('[data-preset-size]');if(btn)applyCanvasPreset(modal,btn.dataset.presetSize)});
 modal.addEventListener('input',e=>{if(e.target.matches('input[type=number]'))updateCanvasPresetSelection(modal)});
}

function openSeriesCreator(){if(!isArtboardSeries()){toast('Серия доступна для карточек');return}const d=app.doc;$('#seriesNewWidth').value=d.width;$('#seriesNewHeight').value=d.height;$('#seriesNewColor').value=/^#[0-9a-f]{6}$/i.test(d.background)?d.background:'#ffffff';const root=$('#seriesTemplateGrid');root.innerHTML='';const templates=projectDocs().filter(doc=>doc.type==='template');if(!templates.length){root.innerHTML='<p>В этом проекте пока нет шаблонов.</p>'}else{for(const t of templates){const b=document.createElement('button');b.className='series-template-item';b.type='button';b.dataset.seriesTemplate=t.id;b.innerHTML=`<strong>${html(t.title)}</strong><small>${t.width} × ${t.height} px</small>`;const canvas=document.createElement('canvas');b.prepend(canvas);root.appendChild(b);try{drawBoardCanvas(canvas,t)}catch(e){console.warn(e)}}}$('#seriesCreateDialog').classList.remove('hidden');updateCanvasPresetSelection($('#seriesCreateDialog'))}
function closeSeriesCreator(){$('#seriesCreateDialog').classList.add('hidden')}
function addBlankSeries(){if(!isArtboardSeries())return;const w=Number($('#seriesNewWidth').value),h=Number($('#seriesNewHeight').value);if(!(Number.isFinite(w)&&w>=100&&w<=5000&&Number.isFinite(h)&&h>=100&&h<=5000)){toast('Размер от 100 до 5000 px');return}const d=app.doc;syncCurrentSlide(d);const blank=newDoc({title:d.title,type:'card',width:Math.round(w),height:Math.round(h)});blank.background=$('#seriesNewColor').value;const slide=makeSlideFromDoc(blank);d.slides.push(slide);closeSeriesCreator();changeSlide(d.slides.length-1,false);fitCanvas();commit()}
function addTemplateSeries(id){const template=projectDocs().find(x=>x.id===id&&x.type==='template');if(!template)return;const d=app.doc;syncCurrentSlide(d);d.slides.push(makeTemplateSlide(template));closeSeriesCreator();changeSlide(d.slides.length-1,false);fitCanvas();commit()}
$('#seriesSidebarAdd').addEventListener('click',openSeriesCreator);$('#seriesCreateClose').addEventListener('click',closeSeriesCreator);$('#seriesCreateDialog').addEventListener('pointerdown',ev=>{if(ev.target.id==='seriesCreateDialog')closeSeriesCreator()});$('#seriesCreateBlank').addEventListener('click',addBlankSeries);$('#seriesTemplateGrid').addEventListener('click',ev=>{const b=ev.target.closest('[data-series-template]');if(b)addTemplateSeries(b.dataset.seriesTemplate)});
$('#seriesSidebarList').addEventListener('click',ev=>{const remove=ev.target.closest('[data-side-remove]');if(remove){ev.preventDefault();removeSeriesSlide(Number(remove.dataset.sideRemove));return}const row=ev.target.closest('[data-side-slide]');if(row)changeSlide(Number(row.dataset.sideSlide),true)});
$('#mobileSeriesToggle').addEventListener('click',()=>{const willOpen=$('#mobileSeriesSheet').classList.contains('hidden');if(willOpen)closeMobileOverlays('series');$('#mobileSeriesSheet').classList.toggle('hidden',!willOpen);syncMobileOverlayState()});
$('#mobileSeriesClose').addEventListener('click',()=>$('#mobileSeriesSheet').classList.add('hidden'));
$('#mobileSeriesAdd').addEventListener('click',()=>{$('#mobileSeriesSheet').classList.add('hidden');openSeriesCreator()});
