function tabPickerImagePreviews(){
 const root=$('#tabPickerGrid');
 for(const node of root.querySelectorAll('[data-tab-picker-preview]')){
  const previewType=tabPicker.step==='cardSource'?'template':tabPicker.category;
  const doc=tabPickerDocuments(tabPicker.projectId,previewType).find(d=>d.id===node.dataset.tabPickerPreview);
  if(!doc)continue;
  try{
   const thumb=document.createElement('canvas');thumb.width=174;thumb.height=Math.max(1,Math.round(174*doc.height/doc.width));
   const ctx=thumb.getContext('2d');ctx.scale(174/doc.width,174/doc.width);
   paintDocument(ctx,slideAsDoc(doc,0),false);
   node.appendChild(thumb);
  }catch(err){console.warn('Не удалось отобразить превью',err)}
 }
}
