 panel.style.left=((vv?.offsetLeft||0)+(vv?.width||innerWidth)/2)+'px';
 panel.style.top=(Math.min(toolbar.top,(vv?.offsetTop||0)+(vv?.height||innerHeight))-panel.getBoundingClientRect().height-8)+'px';
