function unifiedColorControl(el){if(!el||el.dataset.unifiedBound)return;el.dataset.unifiedBound='1';
 const btn=document.createElement('button');btn.type='button';btn.className='unified-color-button';btn.title='Открыть редактор цвета';btn.style.background=el.value||'#7857de';btn.dataset.unifiedColor='1';el.insertAdjacentElement('afterend',btn);el.style.display='none';
 btn.addEventListener('click',ev=>{ev.preventDefault();ev.stopPropagation();const fId=el.dataset.fxField,k=el.dataset.fxKey;
  if(fId){const p=$('#fillPopover');if(!p.classList.contains('hidden')&&p.dataset.key==='_effect')closeFillPopover();p.dataset.effectId=fId;p.dataset.effectField=k||'color';openFillPopover('_effect',btn);return}
  if(el.dataset.key){openFillPopover(el.dataset.key,btn);return}
  if(el.id==='rasterFillColor'){openFillPopover('rasterFillColor',btn);return}
  // Existing change handlers remain the single source of truth.
  const p=$('#fillPopover');p.dataset.effectId='';p.dataset.effectField='color';openFillPopover('_effect',btn);
 });
}
const unifyColorControls=()=>document.querySelectorAll('input[type="color"]').forEach(unifiedColorControl);
new MutationObserver(()=>unifyColorControls()).observe(document.body,{subtree:true,childList:true});unifyColorControls();

