async function zipSavedSnapshot(){
 if(projectOperation||zipWorkspaceBusy)throw Error('Дождись завершения операции с проектами');
 zipWorkspaceBusy=true;
 let timer,cancelled=false;
 const ensureActive=()=>{if(cancelled)throw Error('Подготовка снимка отменена после ожидания хранилища')};
 try{
  const barrier=(async()=>{
   await workspaceBarrier.drain();
   ensureActive();
   // Finish text/raster input exactly as a normal tab switch does.
   captureDocumentTab();
   if(!await flushSave())throw Error('Сохранение активного документа не подтверждено. Не закрывай приложение');
   for(const tab of documentTabSession.tabs){
    ensureActive();
    if(tab.view.historyPreviewOriginal)throw Error('Выйди из предпросмотра истории во всех вкладках');
    const rec=clone(tab.doc);
    if(!await saveDocumentSnapshot(rec)||JSON.stringify(rec)!==JSON.stringify(tab.doc))throw Error('Сохранение вкладки не подтверждено. Не закрывай приложение');
   }
   await workspaceBarrier.drain();
  })();
  await Promise.race([barrier,new Promise((_,reject)=>{timer=setTimeout(()=>{cancelled=true;reject(Error('Сохранения не завершены за 30 секунд. Дождись хранилища и повтори. Сохранение не подтверждено'))},30000)})]);
  return await readWorkspaceSnapshot(app.db);
 }finally{cancelled=true;clearTimeout(timer);zipWorkspaceBusy=false}
}
const workspaceReplacement=createReplacementSession({
 db:()=>app.db,
 storage:{getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value),removeItem:key=>localStorage.removeItem(key)},
 download:downloadBlob,
 begin:async()=>{
  if(replacementFrozen||projectOperation||zipWorkspaceBusy)throw Error('Дождись завершения текущей операции');
  replacementFrozen=true;
  try{
   await workspaceInstances.acquire();
   mobileV36EndNudge();
   if(v39Pending){clearTimeout(v39Pending.timer);v39Pending=null}
   const data=await zipSavedSnapshot();
   replacementSealed=true;
   clearTimeout(app.saveTimer);app.saveTimer=null;
   return data;
  }catch(error){replacementFrozen=false;await workspaceInstances.release();throw error}
 },
 end:async()=>{
  if(replacementStopped)return;
  replacementSealed=false;replacementFrozen=false;
  await workspaceInstances.release();
 },
 stop:()=>{
  replacementStopped=true;replacementSealed=true;
  clearTimeout(app.saveTimer);app.saveTimer=null;
  clearTimeout(mobileV36NudgeTimer);clearInterval(mobileV36NudgeTimer);mobileV36NudgeTimer=null;
  if(v39Pending){clearTimeout(v39Pending.timer);v39Pending=null}
  app.doc=null;documentTabSession.tabs.length=0;documentSaves.clear();
  app.db?.close();app.db=null;
 },
 reload:failures=>{
  const result={committed:true,failures};
  try{sessionStorage.setItem('kartochnaya-workspace-restored',JSON.stringify(result))}
  catch{alert(workspaceRestoreMessage(result))}
  location.reload();
 }
});
function workspaceRestoreMessage(result){return result.failures.length?'IndexedDB восстановлена. Частичное восстановление настроек: localStorage недоступен для '+result.failures.join(', ')+'. Проверь настройки после перезагрузки.':'Рабочее пространство восстановлено: транзакция IndexedDB подтверждена.'}
function showWorkspaceRestoreResult(){
 try{
  const raw=sessionStorage.getItem('kartochnaya-workspace-restored');sessionStorage.removeItem('kartochnaya-workspace-restored');
  if(!raw)return;const result=JSON.parse(raw);if(result.committed!==true||!Array.isArray(result.failures))return;
  if(result.failures.length)alert(workspaceRestoreMessage(result));else toast(workspaceRestoreMessage(result));
 }catch{}
}
const zipBackupUI=installBackupUI({
 replacement:workspaceReplacement,
 snapshot:zipSavedSnapshot,
 download:downloadBlob,
 restore:async (verified,checkActive=()=>{})=>{
  const existing=await zipSavedSnapshot();
  checkActive();
  // No asynchronous gap before importProjectSet acquires its existing lock.
  const diagnostics=await importProjectSet({fonts:verified.data.fonts},verified.data.projects.map(project=>({project,documents:verified.data.docs.filter(doc=>doc.projectId===project.id)})),Number.MAX_SAFE_INTEGER,existing,checkActive);
  renderDocumentTabs();
  return [...verified.warnings,...diagnostics.warnings.map(item=>item.code+' ('+item.path+')')];
 }
});

